	"{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://tasknotes.dev/schemas/tasknotes-task-binding.schema.json\",\n  \"title\": \"TaskNotes task data-contract binding\",\n  \"description\": \"Semantic configuration supplied by an mdbase type that implements tasknotes.task 0.3.0-rc.3.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"profiles\",\n    \"capabilities\",\n    \"title\",\n    \"status\",\n    \"priority\",\n    \"recurrence\",\n    \"occurrences\",\n    \"links\",\n    \"archive\",\n    \"time_tracking\",\n    \"templating\"\n  ],\n  \"properties\": {\n    \"profiles\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"uniqueItems\": true,\n      \"items\": {\n        \"enum\": [\n          \"core-lite\",\n          \"recurrence\",\n          \"templating\",\n          \"materialized-occurrences\",\n          \"extended\"\n        ]\n      }\n    },\n    \"capabilities\": {\n      \"type\": \"array\",\n      \"uniqueItems\": true,\n      \"items\": {\n        \"enum\": [\n          \"dependencies\",\n          \"reminders\",\n          \"attachments\",\n          \"links\",\n          \"time-tracking\",\n          \"materialized-occurrences\",\n          \"rename\",\n          \"archive\",\n          \"batch\",\n          \"concurrency\",\n          \"dry-run\",\n          \"migration\",\n          \"templating\"\n        ]\n      }\n    },\n    \"title\": {\n      \"$ref\": \"#/$defs/titlePolicy\"\n    },\n    \"status\": {\n      \"$ref\": \"#/$defs/statusPolicy\"\n    },\n    \"priority\": {\n      \"$ref\": \"#/$defs/priorityPolicy\"\n    },\n    \"recurrence\": {\n      \"$ref\": \"#/$defs/recurrencePolicy\"\n    },\n    \"occurrences\": {\n      \"$ref\": \"#/$defs/occurrencePolicy\"\n    },\n    \"links\": {\n      \"$ref\": \"#/$defs/linkPolicy\"\n    },\n    \"archive\": {\n      \"$ref\": \"#/$defs/archivePolicy\"\n    },\n    \"time_tracking\": {\n      \"$ref\": \"#/$defs/timeTrackingPolicy\"\n    },\n    \"templating\": {\n      \"$ref\": \"#/$defs/templatingPolicy\"\n    },\n    \"nlp\": {\n      \"$ref\": \"#/$defs/nlpPolicy\"\n    }\n  },\n  \"additionalProperties\": false,\n  \"$defs\": {\n    \"nonEmptyString\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"stringSet\": {\n      \"type\": \"array\",\n      \"uniqueItems\": true,\n      \"items\": {\n        \"$ref\": \"#/$defs/nonEmptyString\"\n      }\n    },\n    \"titlePolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"storage\"\n      ],\n      \"properties\": {\n        \"storage\": {\n          \"enum\": [\n            \"filename\",\n            \"frontmatter\"\n          ]\n        },\n        \"filename_format\": {\n          \"enum\": [\n            \"title\",\n            \"zettel\",\n            \"timestamp\",\n            \"uuid\",\n            \"custom\"\n          ]\n        },\n        \"custom_filename_template\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        }\n      },\n      \"allOf\": [\n        {\n          \"if\": {\n            \"properties\": {\n              \"filename_format\": {\n                \"const\": \"custom\"\n              }\n            },\n            \"required\": [\n              \"filename_format\"\n            ]\n          },\n          \"then\": {\n            \"properties\": {\n              \"custom_filename_template\": {\n                \"$ref\": \"#/$defs/nonEmptyString\"\n              }\n            },\n            \"required\": [\n              \"custom_filename_template\"\n            ]\n          }\n        }\n      ],\n      \"additionalProperties\": true\n    },\n    \"statusDefinition\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"value\",\n        \"label\",\n        \"color\",\n        \"is_completed\",\n        \"is_skipped\",\n        \"exclude_from_cycle\",\n        \"order\",\n        \"auto_archive\",\n        \"auto_archive_delay_minutes\"\n      ],\n      \"properties\": {\n        \"value\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"label\": {\n          \"type\": \"string\"\n        },\n        \"color\": {\n          \"type\": \"string\"\n        },\n        \"icon\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"is_completed\": {\n          \"type\": \"boolean\"\n        },\n        \"is_skipped\": {\n          \"type\": \"boolean\"\n        },\n        \"exclude_from_cycle\": {\n          \"type\": \"boolean\"\n        },\n        \"next_status\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"order\": {\n          \"type\": \"number\"\n        },\n        \"auto_archive\": {\n          \"type\": \"boolean\"\n        },\n        \"auto_archive_delay_minutes\": {\n          \"type\": \"number\",\n          \"minimum\": 0\n        }\n      },\n      \"additionalProperties\": true\n    },\n    \"statusPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"values\",\n        \"default\",\n        \"completed_values\",\n        \"definitions\"\n      ],\n      \"properties\": {\n        \"values\": {\n          \"$ref\": \"#/$defs/stringSet\"\n        },\n        \"default\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"completed_values\": {\n          \"$ref\": \"#/$defs/stringSet\"\n        },\n        \"skipped_values\": {\n          \"$ref\": \"#/$defs/stringSet\"\n        },\n        \"default_skipped\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"definitions\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/statusDefinition\"\n          }\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"priorityDefinition\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"value\",\n        \"label\",\n        \"color\",\n        \"weight\"\n      ],\n      \"properties\": {\n        \"value\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"label\": {\n          \"type\": \"string\"\n        },\n        \"color\": {\n          \"type\": \"string\"\n        },\n        \"icon\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"weight\": {\n          \"type\": \"number\"\n        }\n      },\n      \"additionalProperties\": true\n    },\n    \"priorityPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"values\",\n        \"default\",\n        \"definitions\"\n      ],\n      \"properties\": {\n        \"values\": {\n          \"$ref\": \"#/$defs/stringSet\"\n        },\n        \"default\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"definitions\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/priorityDefinition\"\n          }\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"recurrencePolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"syntax\",\n        \"maintain_due_date_offset\",\n        \"reset_body_checkboxes\"\n      ],\n      \"properties\": {\n        \"syntax\": {\n          \"const\": \"tasknotes\"\n        },\n        \"maintain_due_date_offset\": {\n          \"type\": \"boolean\"\n        },\n        \"reset_body_checkboxes\": {\n          \"type\": \"boolean\"\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"occurrencePolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"identity_roles\",\n        \"default_materialization\",\n        \"default_next_trigger\"\n      ],\n      \"properties\": {\n        \"identity_roles\": {\n          \"const\": [\n            \"recurrenceParent\",\n            \"occurrenceDate\"\n          ]\n        },\n        \"default_materialization\": {\n          \"enum\": [\n            \"manual\",\n            \"on_completion\",\n            \"rolling\"\n          ]\n        },\n        \"default_next_trigger\": {\n          \"enum\": [\n            \"completion\",\n            \"completion_or_skip\"\n          ]\n        },\n        \"past_horizon\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"future_horizon\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"linkPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"accepted_formats\",\n        \"write_format\"\n      ],\n      \"properties\": {\n        \"accepted_formats\": {\n          \"type\": \"array\",\n          \"minItems\": 1,\n          \"uniqueItems\": true,\n          \"items\": {\n            \"enum\": [\n              \"wikilink\",\n              \"markdown\"\n            ]\n          }\n        },\n        \"write_format\": {\n          \"enum\": [\n            \"wikilink\",\n            \"markdown\"\n          ]\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"archivePolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"archived_tag\",\n        \"move_on_archive\"\n      ],\n      \"properties\": {\n        \"archived_tag\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"move_on_archive\": {\n          \"type\": \"boolean\"\n        },\n        \"folder\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"timeTrackingPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"auto_stop_on_complete\"\n      ],\n      \"properties\": {\n        \"auto_stop_on_complete\": {\n          \"type\": \"boolean\"\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"templatingPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"enabled\",\n        \"occurrence_enabled\"\n      ],\n      \"properties\": {\n        \"enabled\": {\n          \"type\": \"boolean\"\n        },\n        \"template_path\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"occurrence_enabled\": {\n          \"type\": \"boolean\"\n        },\n        \"occurrence_template_path\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"failure_mode\": {\n          \"enum\": [\n            \"error\",\n            \"warning_fallback\"\n          ]\n        },\n        \"unknown_variable_policy\": {\n          \"enum\": [\n            \"preserve\",\n            \"empty\"\n          ]\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"nlpTrigger\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"property_id\",\n        \"trigger\",\n        \"enabled\"\n      ],\n      \"properties\": {\n        \"property_id\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"trigger\": {\n          \"$ref\": \"#/$defs/nonEmptyString\"\n        },\n        \"enabled\": {\n          \"type\": \"boolean\"\n        }\n      },\n      \"additionalProperties\": false\n    },\n    \"nlpPolicy\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"triggers\"\n      ],\n      \"properties\": {\n        \"triggers\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/nlpTrigger\"\n          }\n        }\n      },\n      \"additionalProperties\": false\n    }\n  }\n}\n"
